/* Original guide templates, fed exclusively by the current catalogue. */
window.SAOClassicTemplates={create(c){
'use strict';
const originalMonsterKind=c.monsterKind;c.monsterKind=m=>m.worldBoss?'world':originalMonsterKind(m);
for(const area of c.D.areas)if(area.worldBossId){const list=c.mobAreas.get(area.worldBossId)||[];if(!list.some(x=>x.area.id===area.id))list.push({area,weight:null});c.mobAreas.set(area.worldBossId,list);}
for(const row of c.D.serverGuide?.observedDrops||[]){const list=c.sources.get(row.itemId)||[],key='observed:'+row.monsterId;if(!list.some(x=>x.key===key))list.push({key,kind:c.D.floors.some(f=>f.bossId===row.monsterId)?'boss':'monster',page:'monsters',id:row.monsterId,label:c.mobName(row.monsterId)+'掉落（機率未提供）'});c.sources.set(row.itemId,list);}
for(const row of c.D.serverGuide?.pointShop||[])if(c.items.has(row.id)){const list=c.sources.get(row.id)||[],key='point:'+row.id;if(!list.some(x=>x.key===key))list.push({key,kind:'points',href:'#quests?type=points',label:'點數商店'+(Number.isFinite(row.price)?' · '+c.nf(row.price)+' 點':'')});c.sources.set(row.id,list);}
for(const chapter of c.D.chapters)for(const reward of [chapter.reward,...(chapter.steps||[]).map(x=>x.reward)])for(const id of reward?.choose||[]){
 if(typeof id!=='string'||!c.items.has(id))continue;const list=c.sources.get(id)||[],key='choice:'+chapter.id;
 if(!list.some(x=>x.key===key))list.push({key,kind:'quest',page:'quests',id:chapter.id,label:'章節獎勵（擇一） · '+(c.known(c.text(chapter.title))?c.text(chapter.title):chapter.id)});c.sources.set(id,list);
}
for(const row of Object.values(c.D.legacyMonsters||{}))for(const drop of row.drops){const list=c.sources.get(drop.itemId)||[],key='legacy:'+row.id;if(!list.some(x=>x.key===key))list.push({key,kind:'legacy',page:'monsters',id:row.id,label:c.mobName(row.id)+'掉落（舊版參考）'});c.sources.set(drop.itemId,list);}
const {G,D,main,$,esc,nf,pct,named,text,known,items,mobs,areas,styles,slots,quality,kinds,statName,val,rate,sourceHTML,sources,mobAreas,mobName,itemName,areaName,href,goalText,titleChapter,rewardText}=c;
const materialCatalogue=window.SAOMaterialCatalogue.create(c);
const E={styles},slotNames={...slots,weapon:'武器',accessory:'戒指',ear:'耳環'},rateStats=new Set(['crit','critDmg','block','evade']);
const rawEquipment=c.equipment,guide={equipment:rawEquipment.map(x=>({...x,bonus:x.bonus||{},name:named(x),quality:quality[G.quality(x)]}))};
const equipMap=new Map(guide.equipment.map(x=>[x.id,x]));
window.SAORefreshGuideCatalogue=()=>{
 for(const [map,list] of [[items,D.items],[mobs,D.monsters],[areas,D.areas]]){map.clear();for(const x of list)map.set(x.id,x)}
 rawEquipment.splice(0,rawEquipment.length,...D.items.filter(x=>x.kind==='equipment'));
 guide.equipment.splice(0,guide.equipment.length,...rawEquipment.map(x=>({...x,bonus:x.bonus||{},name:named(x),quality:quality[G.quality(x)]})));
 equipMap.clear();for(const x of guide.equipment)equipMap.set(x.id,x);
};
const equipmentEffect=x=>text(x.fx).replace(/\{([^{}]+)\}/g,(placeholder,key)=>typeof x.fxRange?.[key]==='string'?x.fxRange[key]:placeholder);
const intro=(eye,title,desc,extra='')=>`<div class="page-intro"><div><div class="eyebrow">${eye}</div><h1>${title}</h1><p>${desc}</p></div>${extra}</div>`;
const heading=(title,desc='',extra='')=>`<div class="section-title"><div><h2>${title}</h2>${desc?'<p>'+desc+'</p>':''}</div>${extra}</div>`;
const link=href,tag=c.tag,noResults=c.empty,table=c.table;
const styleOptions=Object.entries(styles).filter(([k])=>k!=='holy').map(([k,v])=>`<option value="${k}">${v}</option>`).join('');
const floorOptions='<option value="all">全部樓層</option>'+D.floors.map(x=>`<option value="${x.floor}">第 ${x.floor} 層</option>`).join('');
const pending='<span class="subtle">待確認</span>';
const equipmentSources=new Map(guide.equipment.map(x=>{const s=sources.get(x.id)||[];return[x.id,{shop:s.filter(y=>y.kind==='shop'),quest:s.filter(y=>y.kind==='quest'),monster:s.filter(y=>y.kind==='monster'),boss:s.filter(y=>y.kind==='boss'),points:s.filter(y=>y.kind==='points'),legacy:s.filter(y=>y.kind==='legacy'),search:s.map(y=>y.label).join(' ').toLowerCase()}];}));
const sourceApi={matches:(x,k)=>k==='all'||(k==='unknown'?!x.shop.length&&!x.quest.length&&!x.monster.length&&!x.boss.length&&!x.points.length&&!x.legacy.length:!!x[k]?.length)};
function sourceSummary(x){const s=sources.get(x.id)||[];return s.length?`<div class="gear-source-summary">${s.slice(0,3).map(y=>`<span>${esc(y.label)}</span>`).join('')}<button class="text-link" data-equipment="${esc(x.id)}">查看取得方式 →</button></div>`:'來源尚未確認';}
function openEquipment(id){const x=items.get(id);if(!x)return;const pairs=[['需求等級','Lv'+(x.reqLevel||1)],...Object.entries(x.bonus||{}).map(([k,v])=>[statName(k),(v>0?'+':'')+val(k,v)])];if(x.weaponType)pairs.push(['武器攻速',nf(x.speed||100)]);c.detail(named(x),`<div class="tag-row">${tag(slotNames[x.slot]||x.kind)}${x.kind==='equipment'?tag(quality[G.quality(x)],'gold'):''}</div><div class="detail-stats">${pairs.map(([k,v])=>`<div class="detail-stat"><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('')}</div>${known(text(x.fx))?'<section><h3>特殊效果</h3><p>'+esc(equipmentEffect(x))+'</p></section>':''}<p>以上為基底參考值；實際裝備的詞條與強化後性能可能不同。</p><section class="equipment-source-section"><h3>取得方式</h3><p>${sourceHTML(id)}</p></section><a class="button" href="#build?item=${encodeURIComponent(id)}">帶入配裝模擬器 →</a>`);}
main.addEventListener('click',e=>{const b=e.target.closest('[data-equipment]');if(b)openEquipment(b.dataset.equipment);});
function home(){
 const materials=D.chapters.flatMap(x=>(x.steps||[]).filter(s=>s.goal?.kind==='collect'));
 const entries=[['account','◎','帳號查詢','查看角色、裝備與已學技能。','查詢會中斷原遊戲登入'],['monsters','◉','怪物圖鑑','查怪物能力、出沒地點與掉落。',`${D.monsters.length} 種怪物 · 含活動世界王`],['materials','◇','素材圖鑑','查素材用途、取得來源與已確認茸配配方。',`${window.SAOMaterialCatalogue.buildIndex(D,sources).rows.length} 項素材與任務物品`],['materials?view=quests','◇','任務素材（獨特）','查指定收集怪物、數量與任務步驟。',`${materials.length} 個收集步驟`],['bosses','♜','魔王掉落','逐層查看頭目與取得資訊。',`第 1–${D.floorCap} 層配置`],['equipment','⚔','裝備圖鑑','依部位、武器分類與名稱篩選，逐欄比較基礎性能。',`${rawEquipment.length} 件裝備`],['skills','✦','武器技能圖鑑','查攻擊與增益技能，比較各級性能與附加效果。',`${D.skills.length} 招攻擊 ＋ ${D.buffs.length} 招增益`],['achievements','♕','成就圖鑑','查已知成就條件與獎勵稱號。',`${window.SAO_ACHIEVEMENTS.total} 項成就`],['unique','✧','獨特技能','查流派專屬技能與取得流程。','八種流派'],['build','◈','配裝模擬器','選擇各部位裝備與強化方向，即時查看整套能力。','逐件強化 · 能力總覽'],['speed','↗','攻速與敏捷試算','帶入武器攻速與角色敏捷，計算新版普攻間隔。','攻速軟上限 · 間隔試算'],['floors','▤','樓層與掛機區域','比較一般區域、迷宮、秘境與頭目房配置。',`${D.areas.length} 個區域`],['talents','✧','天賦與分支','查特色天賦與技能分支。',`${D.talents.length} 個特色天賦`],['quests','◇','商店與任務','依樓層查章節、支線與商店商品。',`${D.sideQuests.length} 個支線任務`]];
 main.innerHTML=`<section class="hero"><div><div class="eyebrow">SNORED ART ONLINE / 玩家攻略資料庫</div><h1>找素材、查掉落，<br>讓每一步<em>都有方向。</em></h1><p>從一件任務素材，到一套攻速配裝。把樓層、裝備與技能資料放在一起，快速查到你需要的答案。</p><form class="hero-search" id="home-search-form"><label class="sr-only" for="home-search">搜尋攻略名稱</label><input id="home-search" type="search" placeholder="搜尋素材、魔王、裝備、技能…"><button class="button" type="submit">搜尋</button></form></div><div class="hero-aside"><span class="aside-label">這次想查什麼？</span><h2>先找到目標，<br>再決定去哪一層。</h2><p>目前收錄第 1–${D.floorCap} 層配置，實際開放進度以遊戲為準。</p><a class="button" href="#materials?view=quests">查看任務素材掉落 <span>→</span></a><a class="button secondary" href="#speed">試算攻速與敏捷 <span>→</span></a></div></section><div class="stat-grid"><div class="stat"><strong>${materials.length}</strong><span>任務收集步驟</span><small>指定目標與需求數量</small></div><div class="stat"><strong>${D.floorCap}</strong><span>樓層頭目配置</span><small>不代表目前均已開放</small></div><div class="stat"><strong>${rawEquipment.length}</strong><span>裝備資料</span><small>保留每一項能力數值</small></div><div class="stat"><strong>8</strong><span>技能流派</span><small>技能性能與取得流程</small></div></div>${heading('從這裡開始','選一個分類，直接查你正在找的資訊。')}<div class="entry-grid">${entries.map(([p,i,t,d,b])=>`<a class="entry" href="#${p}"><div class="entry-icon">${i}</div><h3>${t}</h3><p>${d}</p><div class="entry-bottom"><span>${b}</span><span>查看 →</span></div></a>`).join('')}</div><div class="home-columns"><section>${heading('任務收集目標','從任務步驟查指定的素材與怪物。','<a href="#materials?view=quests">查看全部 →</a>')}<div class="panel">${materials.slice(0,6).map(s=>`<p><a href="${href('equipment',s.goal.itemId)}">${esc(itemName(s.goal.itemId))}</a> · ${s.goal.qty} 件 · ${s.goal.from?esc(mobName(s.goal.from)):'劇情條件'}</p>`).join('')}</div></section><section>${heading('配裝與技能','依隊伍定位比較裝備與天賦。')}<div class="panel"><h3>坦克、輔助還是輸出？</h3><p>在配裝模擬器選擇定位，再依實際詞條與遊戲中能力調整。</p><a class="button secondary" href="#build">開啟配裝模擬器 →</a></div></section></div><div class="notice"><strong>資料狀態：</strong>已補入部分怪物獎勵、樓層掉落、${Object.keys(D.serverGuide?.bosses||{}).length} 份頭目攻略與完整成就獎勵。其餘欄位仍逐項補全。</div>`;
 $('home-search-form').onsubmit=e=>{e.preventDefault();$('global-search').value=$('home-search').value;$('search-trigger').click();};
}
function equipment(params){
 const D=guide;
 if(params.get('id')&&!equipMap.has(params.get('id'))&&items.has(params.get('id')))return c.itemDetail(params.get('id'));
 let page=1,sortKey='reqLevel',sortDir='asc',total=1;const pageSize=40,qualities=Object.values(quality);
 const columns=[['name','裝備名稱'],['quality','品質'],['slot','部位'],['type','分類'],['reqLevel','需求等級'],['atk','攻擊'],['def','防禦'],['maxHp','HP'],['agi','敏捷'],['speed','武器攻速'],['crit','爆擊率'],['critDmg','爆擊傷害'],['block','格擋'],['evade','迴避'],['slow','盾牌減速'],['source','來源']];
 const textKeys=new Set(['name','slot','type']),sortColumns=columns.filter(([k])=>k!=='source');
 const typeName=x=>x.weaponType?E.styles[x.weaponType]:x.shield?'盾牌':null;
 function value(x,k){if(k==='name')return x.name;if(k==='quality')return qualities.indexOf(x.quality);if(k==='slot')return slotNames[x.slot];if(k==='type')return typeName(x);if(k==='reqLevel')return x.reqLevel;if(k==='speed')return x.speed??null;if(k==='slow')return x.shield?(x.slow??null):null;return x.bonus[k]??null}
 function compare(a,b){const av=value(a,sortKey),bv=value(b,sortKey);if(av===null||bv===null)return av===bv?0:av===null?1:-1;const d=textKeys.has(sortKey)?String(av).localeCompare(String(bv),'zh-Hant',{numeric:true}):av-bv;return sortDir==='asc'?d:-d}
 function cell(x,k){
  if(k==='name')return `<button class="text-link" data-equipment="${esc(x.id)}">${esc(x.name)}</button>`;
  if(k==='quality')return tag(x.quality,x.quality==='專名'?'gold':x.quality==='稀有'?'purple':x.quality==='精良'?'blue':'');
  if(k==='slot')return esc(slotNames[x.slot]);if(k==='type')return esc(typeName(x)||'—');if(k==='reqLevel')return `Lv${x.reqLevel}`;
  if(k==='source')return sourceSummary(x);
  const v=value(x,k);if(v===null)return '<span class="subtle">—</span>';const rate=rateStats.has(k)||k==='slow',signed=k!=='speed'&&k!=='slow';return `<span class="${v<0?'negative':signed&&v>0?'positive':''}">${signed&&v>0?'+':''}${rate?pct(v):nf(v)}</span>`;
 }
 main.innerHTML=intro('DATABASE / EQUIPMENT','裝備圖鑑','品質與每項基礎性能分欄比較。點欄名切換升冪／降冪，也可在排序選單直接選擇性能。')+`<div class="filters"><input id="gear-search" aria-label="搜尋裝備或取得來源" type="search" placeholder="搜尋裝備、怪物、商店或任務…"><select id="gear-slot" aria-label="裝備部位"><option value="all">全部裝備部位</option>${Object.entries(slotNames).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select><select id="gear-style" aria-label="武器分類"><option value="all">全部武器分類</option>${styleOptions}<option value="shield">盾牌</option></select><select id="gear-quality" aria-label="裝備品質"><option value="all">全部品質</option>${qualities.map(q=>`<option value="${q}">${q}</option>`).join('')}</select><select id="gear-source" aria-label="裝備來源"><option value="all">全部裝備來源</option><option value="monster">怪物掉落（一般／稀有／秘境／主線）</option><option value="boss">頭目掉落</option><option value="shop">商店販售</option><option value="points">點數商店</option><option value="legacy">舊版掉落參考</option><option value="quest">任務取得</option><option value="unknown">來源尚未確認</option></select><span class="count" id="gear-count" aria-live="polite"></span></div><div class="gear-sortbar"><label for="gear-sort">排序欄位</label><select id="gear-sort" aria-label="裝備排序欄位">${sortColumns.map(([k,t])=>`<option value="${k}">${t}</option>`).join('')}</select><button id="gear-direction" class="button secondary small" aria-label="切換排序方向"></button><span id="gear-sort-status" class="subtle" aria-live="polite"></span></div><p class="section-note" id="gear-help">表格可左右捲動，裝備名稱與欄名會固定。來源可同時包含怪物、頭目、商店及任務；點「查看取得方式」可查怪物、區域與機率。排序涵蓋全部篩選結果；「—」表示無此性能，升冪或降冪都排在有數值的裝備後面。</p><div class="table-wrap gear-table-wrap" role="region" aria-label="裝備性能比較表，可左右捲動" aria-describedby="gear-help" tabindex="0"><table class="gear-table"><caption class="sr-only">裝備品質與完整基礎性能比較</caption><thead><tr>${columns.map(([k,t])=>`<th scope="col" data-gear-column="${k}"${k==='source'?'':' aria-sort="none"'}>${k==='source'?t:`<button class="gear-sort-button" data-gear-sort="${k}" aria-label="${t}排序">${t}<span aria-hidden="true">↕</span></button>`}</th>`).join('')}</tr></thead><tbody id="gear-results"></tbody></table></div><div class="filters"><button class="button secondary small" id="gear-prev">← 上一頁</button><span class="subtle" id="gear-page" aria-live="polite"></span><button class="button secondary small" id="gear-next">下一頁 →</button></div><p class="section-note">數值均為未強化基礎值。品質依一般、精良、稀有、專名排列；點裝備名稱可查看完整資料與攻速試算入口。同名裝備可能有不同品質，不含所有隨機詞條變化。</p>`;
 if(params.get('id')){const x=equipMap.get(params.get('id'));if(x)$('gear-search').value=x.name}if(params.get('q'))$('gear-search').value=params.get('q');if(['monster','boss','shop','points','legacy','quest','unknown'].includes(params.get('source')))$('gear-source').value=params.get('source');
 function render(){
  const q=$('gear-search').value.trim().toLocaleLowerCase(),slot=$('gear-slot').value,type=$('gear-style').value,quality=$('gear-quality').value,source=$('gear-source').value;
  const rows=D.equipment.filter(x=>(!q||x.name.toLocaleLowerCase().includes(q)||equipmentSources.get(x.id).search.includes(q))&&(slot==='all'||x.slot===slot)&&(type==='all'||type==='shield'&&x.shield||type===x.weaponType)&&(quality==='all'||x.quality===quality)&&sourceApi.matches(equipmentSources.get(x.id),source)).sort(compare);
  total=Math.max(1,Math.ceil(rows.length/pageSize));page=Math.min(page,total);$('gear-count').textContent=`${rows.length} / ${D.equipment.length} 件裝備`;
  $('gear-results').innerHTML=rows.length?rows.slice((page-1)*pageSize,page*pageSize).map(x=>`<tr>${columns.map(([k])=>`<td class="gear-${k}${textKeys.has(k)||k==='quality'||k==='source'?'':' gear-number'}${k===sortKey?' sorted-cell':''}">${cell(x,k)}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${columns.length}">沒有符合的裝備。請調整搜尋或篩選條件。</td></tr>`;
  $('gear-page').textContent=`第 ${page} / ${total} 頁${rows.length?` · 第 ${(page-1)*pageSize+1}–${Math.min(page*pageSize,rows.length)} 件`:''}`;$('gear-prev').disabled=page===1;$('gear-next').disabled=page===total;
  $('gear-sort').value=sortKey;$('gear-direction').textContent=sortDir==='asc'?'由小到大 ↑':'由大到小 ↓';$('gear-sort-status').textContent=`目前：${columns.find(([k])=>k===sortKey)[1]}${sortDir==='asc'?'由小到大':'由大到小'}`;
  main.querySelectorAll('[data-gear-sort]').forEach(b=>{const active=b.dataset.gearSort===sortKey;b.parentElement.setAttribute('aria-sort',active?(sortDir==='asc'?'ascending':'descending'):'none');b.querySelector('span').textContent=active?(sortDir==='asc'?'↑':'↓'):'↕'});
 }
 function chooseSort(key){if(sortKey===key)sortDir=sortDir==='asc'?'desc':'asc';else{sortKey=key;sortDir=key==='quality'||!textKeys.has(key)&&key!=='reqLevel'?'desc':'asc'}page=1;render()}
 main.querySelectorAll('[data-gear-sort]').forEach(b=>b.addEventListener('click',()=>chooseSort(b.dataset.gearSort)));
 $('gear-sort').addEventListener('change',()=>chooseSort($('gear-sort').value));$('gear-direction').addEventListener('click',()=>{sortDir=sortDir==='asc'?'desc':'asc';page=1;render()});
 for(const id of ['gear-search','gear-slot','gear-style','gear-quality','gear-source'])$(id).addEventListener('input',()=>{page=1;render()});$('gear-prev').addEventListener('click',()=>{page=Math.max(1,page-1);render()});$('gear-next').addEventListener('click',()=>{page=Math.min(total,page+1);render()});render();
 if(params.get('id'))requestAnimationFrame(()=>openEquipment(params.get('id')));
}


const numeric=x=>Number.isFinite(x)?nf(x):pending;
const damageTypes={slash:'斬擊',pierce:'穿刺',blunt:'打擊',dragon:'龍傷害'};
function floorPool(floor){const p=D.serverGuide?.floorDrops?.[floor];if(!p)return'';const q={white:'一般',fine:'精良',gold:'稀有',named:'專名',set:'套裝'};return `<details class="monster-drops"><summary>第 ${floor} 層共通掉落</summary><div class="monster-drop-content">${p.gear?`<p>裝備 Lv${p.gear.lo}–${p.gear.hi} · ${p.gear.quals.map(x=>q[x]||x).map(esc).join('、')}</p>`:''}${p.craft?'<p>魔石</p>':''}<p>${(p.items||[]).map(id=>`<a href="${href('equipment',id)}">${esc(itemName(id))}</a>`).join('、')}</p><p class="section-note">這是樓層共通池；未提供各怪物的個別掉落率或頭目專屬掉落。</p></div></details>`;}
function bossGuide(floor){const b=D.serverGuide?.bosses?.[floor];if(!b)return'';const pressure={enrage:'打太久會狂暴，越拖越痛。',stack:'每次大招後攻擊更痛，拖越久疊得越快。',regen:'打太久會開始回血，再拖下去還會狂暴。',summon:'會召喚小怪，拖越久叫越多。'},shapes={single:'單體',combo:'連擊',area:'範圍',summon:'召喚',self:'自身'};return `<section class="monster-boss-skills"><h3>頭目階段與招式</h3><p>${esc(text(b.intro))}</p>${b.phases.map((p,i)=>`<details class="boss-phase-details"${i===0?' open':''}><summary>${i===0?'開場階段':'HP 低於 '+pct(p.below)}</summary><div class="tag-row">${p.dmg?tag(damageTypes[p.dmg]||p.dmg):''}${p.faster?tag('攻速提升','gold'):''}${p.harder?tag('攻擊提升','gold'):''}${p.frenzy?tag(p.crit?'狂暴／暴擊提升':'狂暴','purple'):''}</div>${p.skills.map(k=>`<div class="boss-move-details"><b>${esc(text(k.name))}</b>${D.serverGuide.skills?.[k.id]?.shape?tag(shapes[D.serverGuide.skills[k.id].shape]||D.serverGuide.skills[k.id].shape):''}${known(text(k.note))?'<p>'+esc(text(k.note))+'</p>':''}</div>`).join('')}</details>`).join('')}${pressure[b.pressure]?'<p class="important">'+pressure[b.pressure]+'</p>':''}${known(text(b.canon))?'<p>'+esc(text(b.canon))+'</p>':''}${known(text(b.duo))?'<p>'+esc(text(b.duo))+'</p>':''}</section>`;}

function legacyNumber(value){return `<span class="legacy-value">${nf(value)}<small>舊版參考</small></span>`;}
function recentReward(m,key){return (D.serverGuide?.observedRewards?.[m?.id]||[]).filter(x=>typeof x.at==='string'&&Number.isFinite(Date.parse(x.at))&&Number.isFinite(x[key])).slice().sort((a,b)=>Date.parse(b.at)-Date.parse(a.at)||(b.order||0)-(a.order||0))[0];}
function monsterValue(m,key){
 if(['exp','col'].includes(key)){const row=recentReward(m,key);if(row)return `<span class="observed-value" data-observed-reward="${key}">${nf(row[key])}<small>${row.kind==='average'?'平均實得':'近期擊殺實得'}${row.level?' · Lv'+row.level:''}</small></span>`;}
 const value=['maxHp','atk','def','agi','crit'].includes(key)?m?.stats?.[key]:m?.[key];
 if(Number.isFinite(value))return numeric(value);
 if(key==='maxHp'&&m?.observedMaxHp?.length===1)return numeric(m.observedMaxHp[0]);
 const previous=['maxHp','atk','def','agi','crit'].includes(key)?m?.legacyReference?.stats?.[key]:m?.legacyReference?.[key];
 return Number.isFinite(previous)?legacyNumber(previous):pending;
}
const legacyRate=value=>(value*100).toLocaleString('zh-TW',{maximumFractionDigits:12})+'%';
function legacyDropChance(monsterId,itemId){return mobs.get(monsterId)?.legacyReference?.drops.find(x=>x.itemId===itemId)?.chance??null;}
function monsterLegacyDrops(m){const list=m?.legacyReference?.drops||[];if(!list.length)return '';return `<details class="legacy-drops"><summary>舊版掉落參考（${list.length} 項）</summary><p class="section-note">已排除已知衝突與不相容物品；機率為舊版數值，供暫時參考。</p>${table(['物品','舊版機率'],list.map(x=>`<tr data-drop-item="${esc(x.itemId)}" data-legacy-drop><td><a href="${href('equipment',x.itemId)}">${esc(itemName(x.itemId))}</a></td><td class="legacy-value">${legacyRate(x.chance)}</td></tr>`).join(''))}</details>`;}
function monsterDropRows(m){const list=(D.serverGuide?.observedDrops||[]).filter(x=>x.monsterId===m.id).map(x=>x.itemId);if(!list.length)return '';return `<details class="observed-drops"><summary>已確認掉落（${list.length} 種）</summary><p class="section-note">由累積紀錄確認曾經掉落，可能包含較早版本；不代表完整或現行掉落池，各項機率尚未提供。</p>${table(['物品','部位／種類'],list.map(id=>{const item=items.get(id);return `<tr data-drop-item="${esc(id)}"><td>${item?`<a href="${href('equipment',id)}">${esc(itemName(id))}</a>`:`<span>${esc(id)}</span><small class="v2-sub">物品定義尚未取得</small>`}</td><td>${esc(slotNames[item?.slot]||({material:'素材',potion:'藥水',crystal:'結晶',food:'食物'}[item?.kind]||item?.kind||'—'))}</td></tr>`;}).join(''))}</details>`;}
function monsterMoveRows(m){const list=D.serverGuide?.observedSkills?.[m.id]||[];if(!list.length)return '';const shapes={single:'單體',combo:'連擊',area:'範圍',summon:'召喚',self:'自身'};return `<details class="observed-skills"><summary>已觀察招式（${list.length} 招）</summary>${table(['招式','類型'],list.map(id=>{const skill=D.serverGuide.skills[id];return `<tr><td>${esc(skill?text(skill.name):id)}</td><td>${esc(shapes[skill?.shape]||'未提供')}</td></tr>`;}).join(''))}</details>`;}
function monsterRewardRows(m){const list=D.serverGuide?.observedRewards?.[m.id]||[];if(!list.length)return '';const ordered=list.slice().sort((a,b)=>(Date.parse(b.at)||0)-(Date.parse(a.at)||0)||(b.order||0)-(a.order||0));return `<details class="observed-rewards"><summary>實得經驗與摳（${list.length} 筆）</summary><p class="section-note">擊殺紀錄為當次實得，掛機統計為每隻平均；可能受組隊分配與加成影響，未作為怪物基礎獎勵。快照等級不等於每筆擊殺當時的等級，未記錄的條件保留未知。</p>${table(['角色等級','紀錄類型','經驗／隻','摳／隻','隊伍人數','快照時間'],ordered.map(x=>`<tr><td>${x.level?'Lv'+x.level:x.snapshotLevel?'未確認（快照 Lv'+x.snapshotLevel+'）':'未記錄'}</td><td>${x.kind==='average'?'掛機平均':x.source==='init'?'init 擊殺紀錄':'既有實測'}</td><td>${Number.isFinite(x.exp)?nf(x.exp):'未記錄'}</td><td>${Number.isFinite(x.col)?nf(x.col):'未記錄'}</td><td>${x.partySize||'未記錄'}</td><td>${x.at?esc(new Date(x.at).toLocaleString('zh-TW',{timeZone:'Asia/Taipei'})):'未記錄'}</td></tr>`).join(''))}</details>`;}
function monsterHpNote(m){return m.observedMaxHp?.length?'<p class="section-note">實戰最大 HP：'+m.observedMaxHp.map(nf).join('／')+'。'+(D.floors.some(f=>f.bossId===m.id)||m.worldBoss?'為已觀察戰鬥的數值，不代表所有隊伍、活動與階段。':'')+'</p>':'';}
function monsterCard(m){const loc=mobAreas.get(m.id)||[],world=c.monsterKind(m)==='world',floor=loc[0]?.area.floor||Number(/^f(\d+)/.exec(m.id)?.[1])||1,boss=D.floors.find(f=>f.bossId===m.id),stats=[[m.stats?.maxHp===undefined&&m.observedMaxHp?.length?'HP（實戰）':'HP','maxHp'],['攻擊','atk'],['防禦','def'],['敏捷','agi'],['經驗','exp'],['摳','col']];return`<article class="monster-card ${world?'world-boss':''}" id="monster-${esc(m.id)}"><div class="monster-heading"><div class="floor-badge">${floor}<small>層</small></div><div><div class="tag-row">${tag(c.monsterKinds[c.monsterKind(m)],'blue')}<span class="monster-level">${m.levelUnknown?'等級隱藏 · Lv???':'Lv'+m.level}</span></div><h2>${esc(named(m))}</h2></div></div><div class="monster-body"><dl class="monster-stat-grid">${stats.map(([k,key])=>`<div><dt>${k}</dt><dd>${monsterValue(m,key)}</dd></div>`).join('')}</dl>${m.hit||m.pace?`<div class="tag-row">${m.hit?tag(damageTypes[m.hit]||m.hit):''}${m.pace?tag({normal:'一般節奏',fast:'快速',slow:'緩慢'}[m.pace]||m.pace):''}</div>`:''}<div class="monster-locations"><b>出沒地點</b>${loc.map(({area})=>`<a href="${href('floors',area.id)}">第 ${area.floor} 層 · ${esc(named(area))}</a>`).join('')||'<p>劇情／特殊戰鬥</p>'}</div>${world?'<div class="notice"><strong>活動世界王</strong><p>每場挑戰限時 5 分鐘；實際能力與獎勵以活動資訊為準。</p></div>':''}${monsterHpNote(m)}${boss?bossGuide(boss.floor):floorPool(floor)}${monsterDropRows(m)}${monsterLegacyDrops(m)}${monsterMoveRows(m)}${monsterRewardRows(m)}<p class="section-note">尚未取得的能力與個別掉落率保留為待確認。</p></div></article>`;}
function monstersPage(params){let page=1,total=1;main.innerHTML=intro('DATABASE / MONSTER ENCYCLOPEDIA','怪物圖鑑','按樓層查怪物能力、出沒地點與可能掉落。')+`<div class="notice"><strong>已補入 ${D.serverGuideCoverage.beasts} 種怪物的部分能力／獎勵，以及 ${D.serverGuideCoverage.observedHp} 種實戰 HP、${D.serverGuideCoverage.dropSources} 組掉落來源。</strong>另有 ${D.serverGuideCoverage.legacyMonsters} 種未發現衝突的舊版參考資料，以不同顏色標示。</div><p class="monster-event-link"><a href="#monsters?kind=world">活動世界王 →</a></p><div class="filters"><input id="monster-search" type="search" aria-label="搜尋怪物或區域" placeholder="搜尋怪物、代碼或區域…"><select id="monster-floor" aria-label="怪物樓層">${floorOptions}</select><select id="monster-kind" aria-label="怪物種類"><option value="all">全部種類</option>${Object.entries(c.monsterKinds).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select><select id="monster-sort" aria-label="怪物排序"><option value="floor">依樓層／等級</option><option value="name">依名稱</option></select><button class="button secondary small" id="monster-reset">重設篩選</button><span class="count" id="monster-count"></span></div><div class="monster-grid" id="monster-results"></div><div class="monster-pagination"><button class="button secondary" id="monster-prev">上一頁</button><span id="monster-page"></span><button class="button secondary" id="monster-next">下一頁</button></div>`;
 if(params.get('kind'))$('monster-kind').value=params.get('kind');const selected=mobs.get(params.get('id'));if(selected)$('monster-search').value=named(selected);
 const floor=m=>(mobAreas.get(m.id)||[])[0]?.area.floor||Number(/^f(\d+)/.exec(m.id)?.[1])||1;
 function render(reset=false){if(reset)page=1;const q=$('monster-search').value.toLowerCase(),f=$('monster-floor').value,k=$('monster-kind').value,list=D.monsters.filter(m=>(f==='all'||floor(m)===+f)&&(k==='all'||c.monsterKind(m)===k)&&(!q||(named(m)+' '+m.id+' '+(mobAreas.get(m.id)||[]).map(x=>named(x.area)).join(' ')).toLowerCase().includes(q))).sort((a,b)=>$('monster-sort').value==='name'?named(a).localeCompare(named(b),'zh-Hant'):floor(a)-floor(b)||a.level-b.level);total=Math.max(1,Math.ceil(list.length/18));page=Math.min(page,total);$('monster-results').innerHTML=list.slice((page-1)*18,page*18).map(monsterCard).join('')||noResults();$('monster-count').textContent=`${list.length} / ${D.monsters.length} 種怪物`;$('monster-page').textContent=`第 ${page} / ${total} 頁`;$('monster-prev').disabled=page===1;$('monster-next').disabled=page===total;}
 for(const id of ['monster-search','monster-floor','monster-kind','monster-sort'])$(id).oninput=()=>render(true);$('monster-prev').onclick=()=>{page--;render();};$('monster-next').onclick=()=>{page++;render();};$('monster-reset').onclick=()=>{$('monster-search').value='';$('monster-floor').value='all';$('monster-kind').value='all';render(true);};render();
}
function bosses(params){main.innerHTML=intro('DATABASE / BOSS LOOT','魔王掉落一覽',`第 1–${D.floorCap} 層頭目配置、戰鬥階段與掉落資訊。`)+`<div class="notice gold"><strong>已補入${Object.keys(D.serverGuide?.bosses||{}).length} 份頭目攻略。</strong>階段門檻、招式與戰鬥壓力可直接查看；已確認的頭目掉落也會列出，機率未提供。</div><section class="boss-filter-panel"><div class="filters"><input id="boss-search" type="search" placeholder="搜尋魔王名稱、招式或攻略…"><select id="boss-floor">${floorOptions}</select><button class="button secondary small" id="boss-reset">重設篩選</button><span id="boss-count" class="count"></span></div></section><div id="boss-results" class="boss-grid"></div>`;if(D.floors.some(f=>String(f.floor)===params.get('id')))$('boss-floor').value=params.get('id');function render(){const q=$('boss-search').value.toLowerCase(),f=$('boss-floor').value,list=D.floors.filter(x=>(f==='all'||x.floor===+f)&&(!q||(mobName(x.bossId)+' '+x.bossId+' '+JSON.stringify(D.serverGuide?.bosses?.[x.floor]||{})).toLowerCase().includes(q)));$('boss-count').textContent=list.length+' 層頭目';$('boss-results').innerHTML=list.map(x=>{const m=mobs.get(x.bossId);return`<article class="boss-card"><div class="boss-heading"><div class="floor-badge">${x.floor}<small>層</small></div><div><h2><a href="${href('monsters',x.bossId)}">${esc(mobName(x.bossId))}</a></h2><p>頭目 Lv${m?.level||'?'}</p></div></div><div class="boss-loot">${bossGuide(x.floor)}${monsterDropRows(m)}${monsterLegacyDrops(m)}<p class="section-note">尚未列出的掉落不代表不會掉落。</p></div></article>`;}).join('')||noResults();}for(const id of ['boss-search','boss-floor'])$(id).oninput=render;$('boss-reset').onclick=()=>{$('boss-search').value='';$('boss-floor').value='all';render();};render();}
function materials(){const rows=D.chapters.flatMap(ch=>(ch.steps||[]).map((s,index)=>({ch,s,index})).filter(x=>x.s.goal?.kind==='collect'));main.innerHTML=intro('DATABASE / QUEST ITEMS','任務素材（獨特）','查收集素材的指定怪物、需求數量與任務步驟。')+`<div class="notice"><strong>新版任務素材掉落率待確認。</strong>指定怪物與任務收集條件依目前配置列出。</div><div class="filters"><input id="material-search" type="search" placeholder="搜尋素材、怪物或任務…"><select id="material-floor">${floorOptions}</select><span class="count" id="material-count"></span></div><div id="material-results" class="material-grid"></div>`;function render(){const q=$('material-search').value.toLowerCase(),f=$('material-floor').value,list=rows.filter(({ch,s})=>(f==='all'||ch.floor===+f)&&(!q||(itemName(s.goal.itemId)+' '+mobName(s.goal.from)+' '+titleChapter(ch)).toLowerCase().includes(q)));$('material-count').textContent=list.length+' 個收集步驟';$('material-results').innerHTML=list.map(({ch,s,index})=>{const g=s.goal,m=mobs.get(g.from);return`<article class="material-card"><div class="card-top"><div class="tag-row">${tag('第 '+ch.floor+' 層','blue')}${tag('獨特','purple')}</div><h2><a href="${href('equipment',g.itemId)}">${esc(itemName(g.itemId))}</a></h2><div class="drop-rate"><strong>${legacyDropChance(g.from,g.itemId)===null?'待確認':legacyRate(legacyDropChance(g.from,g.itemId))}</strong><span>${legacyDropChance(g.from,g.itemId)===null?'指定目標的任務掉落率':'舊版掉落率參考'}</span></div><dl class="material-info"><dt>目標</dt><dd>${g.from?`<a href="${href('monsters',g.from)}">${esc(mobName(g.from))}</a>${m?' · Lv'+m.level:''}`:'依劇情條件'}</dd><dt>地點</dt><dd class="location">${(mobAreas.get(g.from)||[]).map(({area})=>`<a href="${href('floors',area.id)}">${esc(named(area))}</a>`).join('<br>')||'未取得固定生成位置'}</dd><dt>任務</dt><dd><a href="${href('quests',ch.id)}">${esc(titleChapter(ch))}</a><div class="subtle">第 ${index+1} 個步驟</div></dd><dt>需求</dt><dd>${g.qty||1} 件</dd></dl></div><div class="card-bottom"><details><summary>任務流程與取得條件</summary><ol class="timeline">${ch.steps.map(t=>'<li>'+goalText(t.goal)+'</li>').join('')}</ol></details></div></article>`;}).join('')||noResults();}for(const id of ['material-search','material-floor'])$(id).oninput=render;render();}
function skills(params){let style=params.get('style')||D.buffs.concat(D.skills).find(s=>s.id===params.get('id'))?.style||'sword';main.innerHTML=intro('DATABASE / WEAPON SKILLS','武器技能圖鑑',`八種流派，共 ${D.skills.length} 招攻擊技能與 ${D.buffs.length} 招增益技能。查各級性能與附加效果。`,'<a class="button secondary" href="#unique">獨特技能與修行 →</a>')+`<div class="skill-style-filters" role="group" aria-label="技能武器流派">${[['all','全部流派'],...Object.entries(styles)].map(([k,t])=>`<button class="skill-style-button" data-skill-style="${k}" aria-pressed="${k===style}">${t}</button>`).join('')}</div><div class="filters"><input id="skills-search" type="search" placeholder="搜尋技能或效果…"><select id="skills-kind"><option value="all">全部技能類型</option><option value="attack">攻擊技能</option><option value="buff">增益技能</option></select><label class="skill-level-control">攻擊技能等級<select id="skills-level">${Array.from({length:10},(_,i)=>`<option value="${i+1}" ${i===9?'selected':''}>技能 Lv${i+1}</option>`).join('')}</select></label><span class="count" id="skills-count"></span></div><div class="notice"><strong>學習與成長：</strong>技能需滿足角色等級、裝備與天賦連接條件。倍率為每段參考倍率，分支、抗性與戰鬥效果會改變實際傷害。</div><div id="skills-results"></div>`;
 function attack(s,lv){const v=G.skillStats(s,lv);return`<article class="weapon-skill-card ${params.get('id')===s.id?'selected':''}" id="skill-${s.id}"><div class="tag-row">${tag(styles[s.style],'blue')}${tag('攻擊技能')}${tag('技能 Lv'+lv,'gold')}</div><h3>${esc(named(s))}</h3><p class="skill-description">${esc(text(s.desc))}</p><div class="skill-learn"><b>學習條件</b><span>角色 Lv${s.reqLevel} ＋ 對應流派與天賦節點</span></div><dl class="skill-metrics">${[['命中次數',v.hits+' 次'],['單次倍率',nf(v.multiplier)+'×'],['總倍率',nf(v.hits*v.multiplier)+'×'],['冷卻時間',nf(v.cooldownMs/1000)+' 秒'],['最多目標',v.targets+' 隻']].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl><div class="skill-effects"><b>附加效果</b>${c.skillEffects(s)||'<p>未另列附加效果。</p>'}</div><details class="skill-levels"><summary>查看 Lv1～Lv10 完整性能</summary>${table(['技能等級','命中','單次倍率','總倍率','冷卻','目標'],Array.from({length:10},(_,i)=>{const x=G.skillStats(s,i+1);return`<tr><td>Lv${i+1}</td><td>${x.hits}</td><td>${nf(x.multiplier)}×</td><td>${nf(x.hits*x.multiplier)}×</td><td>${nf(x.cooldownMs/1000)} 秒</td><td>${x.targets}</td></tr>`;}).join(''))}</details><details class="skill-levels"><summary>查看技能分支</summary>${D.skillPaths.filter(p=>p.skill===s.id).map(p=>`<h4>${esc(text(p.name))}</h4><p>${esc(text(p.desc))}</p>`).join('')}</details></article>`;}
 function buff(s){return`<article class="weapon-skill-card buff-skill-card"><div class="tag-row">${tag(styles[s.style],'blue')}${tag('增益技能','purple')}${tag(s.party?'隊伍增益':'自身增益')}</div><h3>${esc(named(s))}</h3><p class="skill-description">${esc(text(s.desc))}</p><div class="skill-learn"><b>學習條件</b><span>角色 Lv${s.reqLevel} ＋ 對應天賦節點</span></div><dl class="skill-metrics">${[['持續時間',nf(s.ms/1000)+' 秒'],['冷卻時間',nf(s.cooldownMs/1000)+' 秒']].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl><div class="skill-effects"><b>效果</b><p>${Object.entries(s.effect).map(([k,v])=>esc(statName(k))+' '+(v>0?'+':'')+pct(v)).join('、')}</p></div></article>`;}
 function render(){const q=$('skills-search').value,k=$('skills-kind').value,lv=+$('skills-level').value,list=(k==='attack'?D.skills:k==='buff'?D.buffs:D.skills.concat(D.buffs)).filter(s=>(style==='all'||s.style===style)&&(!q||(named(s)+' '+text(s.desc)).includes(q)));$('skills-count').textContent=list.length+' 招技能';$('skills-results').innerHTML=Object.entries(styles).filter(([k])=>style==='all'||k===style).map(([k,t])=>{const rows=list.filter(s=>s.style===k);return rows.length?`<section class="weapon-skill-section">${heading(t)}<div class="weapon-skill-grid">${rows.map(s=>D.skills.includes(s)?attack(s,lv):buff(s)).join('')}</div></section>`:'';}).join('')||noResults();}
 for(const b of main.querySelectorAll('[data-skill-style]'))b.onclick=()=>{style=b.dataset.skillStyle;main.querySelectorAll('[data-skill-style]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));render();};for(const id of ['skills-search','skills-kind','skills-level'])$(id).oninput=render;render();
}
function unique(params){
 const data=G.getUniqueData?.()||{},nums=data.params||{},guide=D.serverGuide?.mechanics?.uniqueGuide||{};
 const kills=Number.isSafeInteger(nums.UNIQUE_KILLS)&&nums.UNIQUE_KILLS>0?nums.UNIQUE_KILLS:null;
 const req=Number.isFinite(nums.UNIQUE_SKILL_REQ)&&nums.UNIQUE_SKILL_REQ>0?nums.UNIQUE_SKILL_REQ:null;
 main.innerHTML=intro('DATABASE / UNIQUE SKILLS','獨特技能與修行條件','八種流派的取得流程、修行要求與已確認效果。','<a class="button secondary" href="#skills">普通攻擊與增益技能 →</a>')+
 '<div class="notice"><strong>修行條件已補齊。</strong>完整被動倍率、獨特劍技數值與專屬分支仍需遊戲回傳；未公開的數字不沿用舊版，也不視為 0。</div>'+
 '<div class="filters"><select id="unique-style" aria-label="獨特技能流派"><option value="all">全部流派</option>'+Object.entries(styles).map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join('')+'</select></div><div class="unique-grid" id="unique-results"></div>';
 if(styles[params.get('id')])$('unique-style').value=params.get('id');
 function render(){const style=$('unique-style').value;
  $('unique-results').innerHTML=Object.entries(D.uniqueNames).filter(([k])=>style==='all'||k===style).map(([k,name])=>{
   const q=D.uniqueQuests[k],required=req?D.skills.filter(x=>x.style===k&&!x.signature&&x.reqLevel<=req):[];
   const training=(kills?'使用'+styles[k]+'擊倒 '+nf(kills)+' 隻怪物':'擊倒數門檻尚未回傳')+(req?'，並將需求等級 Lv'+nf(req)+' 以下的 '+required.length+' 招普通劍技全部練到 Lv10。':'。');
   const step=x=>x.goal?.kind==='train'?esc(training):goalText(x.goal);
   const effectLines=guide.effects?.[k]||[],desc=text(data.descriptions?.[k]);
   const skills=(data.skills||[]).filter(x=>x.style===k),buffs=(data.buffs||[]).filter(x=>x.style===k),perks=(data.perks||[]).filter(x=>x.style===k),branches=(data.branches||[]).filter(x=>skills.some(v=>v.id===x.skill));
   const row=x=>'<li><strong>'+esc(text(x.name)||x.id||'名稱未公開')+'</strong>'+(text(x.desc)?'：'+esc(text(x.desc)):'')+'</li>';
   const received=[...skills,...buffs,...perks];
   return '<article class="unique-card"><div class="unique-header"><span class="unique-symbol">✧</span><div><h2>'+esc(text(name))+'</h2><p>'+styles[k]+'</p></div></div>'+tag('流派專屬','purple')+
    '<h3>取得流程</h3><p class="unique-text important">流程需求攻略樓層 '+nf(q.needFloor)+'；觸發事件以遊戲中的任務為準。</p><ol class="timeline">'+q.steps.map(x=>'<li>'+step(x)+(known(text(x.text))?'<p>'+esc(text(x.text))+'</p>':'')+'</li>').join('')+'</ol>'+
    '<h3>修行要求</h3><p class="unique-text">'+esc(training)+'</p>'+(required.length?'<details><summary>需要練滿的 '+required.length+' 招劍技</summary><ul>'+required.map(x=>'<li>'+esc(text(x.name))+'（需求 Lv'+nf(x.reqLevel)+'）</li>').join('')+'</ul></details>':'')+
    '<p class="section-note">'+esc(guide.training||'')+'</p><h3>啟用與效果</h3><p class="unique-text">'+esc(guide.activation||'')+'</p>'+
    (desc&&known(desc)?'<p class="unique-text">'+esc(desc)+'</p>':'')+(effectLines.length?'<ul>'+effectLines.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':'')+
    (received.length?'<h3>已回傳的專屬招式與被動</h3><ul>'+received.map(row).join('')+'</ul>':'')+(branches.length?'<h3>專屬分支</h3><ul>'+branches.map(row).join('')+'</ul>':'')+'</article>';
  }).join('');
 }
 $('unique-style').oninput=render;render();
}
function floors(params){let page=1,total=1,view=params.get('view')==='secret'?'secret':'rewards';const kind=x=>x.event==='wb'?'world':x.secret?'secret':x.kind==='bossroom'?'boss':x.kind==='labyrinth'?'labyrinth':x.kind==='town'?'town':'field',labels={field:'一般原野',labyrinth:'迷宮',secret:'秘境',boss:'頭目房',town:'城鎮',world:'活動世界王'};main.innerHTML=intro('DATABASE / FLOOR INTELLIGENCE','樓層與怪物獎勵','一般區域、迷宮、秘境與頭目房一起查，保留各項能力與獎勵欄位。')+`<div class="floor-view-tabs"><button class="skill-style-button" data-view="rewards">區域與怪物獎勵</button><button class="skill-style-button" data-view="secret">秘境詳解 <span>${D.areas.filter(x=>x.secret).length}</span></button></div><div class="notice"><strong>已補入圖鑑回覆與近期擊殺實得經驗、摳。</strong>實得值另有標記，可能包含組隊分配或加成；未作為基礎獎勵再次換算。</div><div class="filters"><input id="area-search" type="search" placeholder="搜尋區域或怪物…"><select id="area-floor">${floorOptions}</select><select id="area-kind"><option value="all">全部區域類型</option>${Object.entries(labels).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select><select id="area-sort"><option value="floor">依樓層排序</option><option value="population">同屏上限由多到少</option></select><span class="count" id="area-count"></span></div><div id="floor-reward-results"></div><div class="filters floor-pagination"><button class="button secondary small" id="area-prev">← 上一頁</button><span id="area-page" class="subtle"></span><button class="button secondary small" id="area-next">下一頁 →</button></div>`;const target=areas.get(params.get('id'));if(target){$('area-floor').value=target.floor;$('area-search').value=named(target);}if(params.get('floor'))$('area-floor').value=params.get('floor');
 function render(reset=false){if(reset)page=1;const q=$('area-search').value.toLowerCase(),f=$('area-floor').value,k=$('area-kind').value,list=D.areas.filter(x=>(view!=='secret'||x.secret)&&(f==='all'||x.floor===+f)&&(k==='all'||kind(x)===k)&&(!q||(named(x)+' '+x.id+' '+(x.spawns||[]).map(s=>mobName(s.monsterId)).join(' ')).toLowerCase().includes(q))).sort((a,b)=>$('area-sort').value==='population'?(G.regionCapacity(b)||0)-(G.regionCapacity(a)||0):a.floor-b.floor);total=Math.max(1,Math.ceil(list.length/20));page=Math.min(page,total);const rows=list.slice((page-1)*20,page*20);$('area-count').textContent=list.length+' 個區域';$('area-page').textContent=`第 ${page} / ${total} 頁`;$('area-prev').disabled=page===1;$('area-next').disabled=page===total;main.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===view)));
 $('floor-reward-results').innerHTML=view==='secret'?`<div class="secret-grid">${rows.map(x=>`<article class="panel secret-area-card"><div class="boss-heading"><div class="floor-badge">${x.floor}<small>層</small></div><div><h2>${esc(named(x))}</h2><p>${x.pack?x.pack.join('–')+' 隻／批':'每批數量未提供'}</p></div></div><p>${known(text(x.desc))?esc(text(x.desc)):''}</p>${table(['怪物','等級','出現權重','經驗／隻','摳／隻'],(x.spawns||[]).map(s=>`<tr><td><a href="${href('monsters',s.monsterId)}">${esc(mobName(s.monsterId))}</a></td><td>Lv${mobs.get(s.monsterId)?.level||'?'}</td><td>${s.weight}</td><td>${monsterValue(mobs.get(s.monsterId),'exp')}</td><td>${monsterValue(mobs.get(s.monsterId),'col')}</td></tr>`).join(''))}</article>`).join('')}</div>`:`${[...new Set(rows.map(x=>x.floor))].map(floorPool).filter(Boolean).map(html=>'<section class="panel">'+html+'</section>').join('')}<div class="table-wrap floor-reward-wrap" role="region" aria-label="區域怪物經驗與摳比較表，可左右捲動" tabindex="0"><table class="floor-reward-table"><thead><tr>${['樓層／區域','同屏上限','每批數量','怪物','等級','與你等級差','經驗／隻','等級差倍率','個人經驗推估／隻','摳／隻','個人摳推估／隻'].map(t=>'<th>'+t+'</th>').join('')}</tr></thead><tbody>${rows.map(x=>{const sp=x.spawns?.length?x.spawns:x.event==='wb'?[{monsterId:x.worldBossId||x.wb||'wb-jack'}]:[{}];return sp.map((s,i)=>`<tr${i===0?' class="floor-area-start"':''}>${i===0?`<td rowspan="${sp.length}" class="floor-area-label"><b>${esc(named(x))}</b><span>第 ${x.floor} 層 · ${labels[kind(x)]}</span>${x.shop?.length?`<button class="text-link" data-shop="${esc(x.id)}">商店商品 →</button>`:''}</td><td rowspan="${sp.length}" class="floor-population"><strong>${G.regionCapacity(x)??'未提供'}</strong>${x.spawns?.length?'<br><small>單人自動狩獵</small>':''}</td><td rowspan="${sp.length}" class="nowrap">${x.pack?x.pack.join('–')+' 隻':'未提供'}</td>`:''}<td class="floor-monster-name">${s.monsterId?`<a href="${href('monsters',s.monsterId)}">${esc(mobName(s.monsterId))}</a>`:'—'}</td><td>${s.monsterId?(mobs.get(s.monsterId)?.levelUnknown?'等級隱藏':'Lv'+(mobs.get(s.monsterId)?.level||'?')):'—'}</td><td>—</td><td>${monsterValue(mobs.get(s.monsterId),'exp')}</td><td>${pending}</td><td>${pending}</td><td>${monsterValue(mobs.get(s.monsterId),'col')}</td><td>${pending}</td></tr>`).join('');}).join('')||'<tr><td colspan="11">沒有符合的區域</td></tr>'}</tbody></table></div>`;
 for(const b of main.querySelectorAll('[data-shop]'))b.onclick=()=>{const x=areas.get(b.dataset.shop);c.detail(named(x)+'商店',table(['商品','需求等級','標示價格'],x.shop.map(s=>{const i=items.get(s.itemId);return`<tr><td><a href="${href('equipment',s.itemId)}">${esc(itemName(s.itemId))}</a></td><td>${i?.reqLevel?'Lv'+i.reqLevel:'—'}</td><td>${nf(i?.price||0)} 摳</td></tr>`;}).join('')));};}
 for(const id of ['area-search','area-floor','area-kind','area-sort'])$(id).oninput=()=>render(true);for(const b of main.querySelectorAll('[data-view]'))b.onclick=()=>{view=b.dataset.view;render(true);};$('area-prev').onclick=()=>{page--;render();};$('area-next').onclick=()=>{page++;render();};render();
}
function speed(params){const item=items.get(params.get('id'));main.innerHTML=intro('TOOL / ATTACK SPEED','攻速與敏捷試算','帶入裝備武器攻速與角色總敏捷，計算新版普攻間隔。')+`<div class="speed-grid"><form class="panel speed-controls" id="speed-form"><div class="two-fields"><label class="field">主手類型<select id="s-style">${styleOptions}</select></label><label class="field">目前總敏捷<input id="s-agi" type="number" value="0" step="1"></label></div><label class="field">選擇主手武器<select id="s-weapon"></select></label><label class="field">裝備顯示的武器攻速<input id="s-w" type="number" min="1" value="${item?.speed||100}"><small>填含強化與詞條後的裝備攻速，不是角色面板攻速。</small></label><label class="field">副手搭配<select id="s-off"><option value="none">無副手武器</option><option value="dual">雙持武器</option></select></label><label class="field" id="s-off-label">副手武器攻速<input id="s-off-speed" type="number" min="1" value="100"></label><label class="field">攻速加成（%）<input id="s-bonus" type="number" min="-90" step="any" value="0"></label></form><div><div id="s-caption" class="speed-build-caption"></div><div id="s-results" class="speed-results" aria-live="polite"></div><div class="panel speed-explain"><strong>新版普攻間隔公式</strong><p>加成原值 x = 攻速加成 + 0.006 × 敏捷。正值軟上限 f(x) = x ÷ (1 + x ÷ 3)，負值最低 −90%。</p><p>有效 speed = 武器攻速 ÷100 × [1 + f(x)]。雙持時使用兩把武器的基礎攻速平均。</p><p>普攻間隔 = max[100 毫秒，四捨五入(2000 ÷ speed)]；面板攻速 = 四捨五入(200000 ÷ 普攻間隔)。</p></div></div></div>`;if(item?.weaponType)$('s-style').value=item.weaponType;function options(){const list=rawEquipment.filter(x=>x.weaponType===$('s-style').value);$('s-weapon').innerHTML='<option value="">自行輸入</option>'+list.map(x=>`<option value="${x.id}">${esc(named(x))}</option>`).join('');if(item&&list.includes(item))$('s-weapon').value=item.id;}function render(){const w=Math.max(1,+$('s-w').value||1),off=Math.max(1,+$('s-off-speed').value||1),dual=$('s-off').value==='dual',base=dual?(w+off)/2:w,agi=+$('s-agi').value||0,bonus=(+$('s-bonus').value||0)/100,s=base/100*(1+G.softSpeed(bonus+.006*agi)),ms=G.interval({speed:s});$('s-off-label').hidden=!dual;$('s-caption').textContent=styles[$('s-style').value]+(dual?' · 雙持平均攻速':' · 單主手攻速');$('s-results').innerHTML=`<article class="panel"><h2>目前配裝</h2><dl class="build-summary-grid">${[['面板攻速',G.attackSpeed(ms)],['普攻間隔',nf(ms/1000)+' 秒'],['每分鐘普攻',nf(60000/ms)+' 次'],['武器基礎攻速',nf(base)]].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl></article>`;}$('s-style').onchange=()=>{options();render();};$('s-weapon').onchange=()=>{const x=items.get($('s-weapon').value);if(x)$('s-w').value=x.speed||100;render();};for(const id of ['s-agi','s-w','s-off','s-off-speed','s-bonus'])$(id).oninput=render;$('speed-form').onsubmit=e=>e.preventDefault();options();render();}
function about(){main.innerHTML=intro('HELP / GUIDE','使用說明','查閱攻略、理解數值與使用計算工具。')+`<div class="about-grid"><section class="panel"><h2>收錄內容</h2><p>收錄第 1–${D.floorCap} 層配置，實際開放進度以遊戲為準。</p><ul><li>${rawEquipment.length} 件裝備基底配置。</li><li>${D.monsters.length} 種怪物與 ${D.areas.length} 個區域。</li><li>八種流派、${D.skills.length} 招攻擊、${D.buffs.length} 招增益。</li><li>${D.talents.length} 個特色天賦與 ${D.skillPaths.length} 條技能分支。</li></ul></section><section class="panel"><h2>帳號查詢</h2><p>查詢會中斷目前遊戲登入。取得角色資料後立即斷線，不操作角色，也不儲存帳密或登入憑證。</p></section><section class="panel"><h2>數值與掉落怎麼讀</h2><p>裝備表格列基底參考值，實物可包含不同詞條與強化。新版怪物數值、掉落率及部分套裝／獨特技能效果尚待取得，不沿用舊值。</p><p>「待確認」不是沒有能力或沒有掉落。</p></section><section class="panel"><h2>計算工具</h2><p>配裝與攻速採用新版可確認的常駐計算規則。動態效果與完整實戰 DPS 不在試算範圍。</p><p>配裝設定保存在目前瀏覽器，也可用分享連結保留。</p></section></div>`;}
function classicBosses(params){
 bosses(params);let slot='all',weapon='all';const panel=$('boss-search').closest('.boss-filter-panel'),renderBase=$('boss-search').oninput;
 const slotRows=[['all','依樓層'],['weapon','武器'],['head','頭盔'],['armor','身體'],['offhand','副手'],['feet','鞋子'],['jewelry','飾物'],['hands','手套'],['cape','披風']];
 const weaponRows=[['all','全部武器'],...Object.entries(styles).filter(([k])=>k!=='holy')];
 const pills=(rows,key)=>rows.map(([v,t])=>`<button type="button" class="boss-filter-button" data-${key}="${v}" aria-pressed="${v==='all'}">${t}</button>`).join('');
 panel.insertAdjacentHTML('afterbegin',`<div id="boss-slot-filters" class="boss-filter-row" role="group" aria-label="裝備部位">${pills(slotRows,'boss-slot')}</div><div id="boss-weapon-filters" class="boss-filter-row boss-weapon-filters" role="group" aria-label="武器類型" hidden>${pills(weaponRows,'boss-weapon')}</div>`);
 function render(){renderBase();$('boss-weapon-filters').hidden=slot!=='weapon';for(const b of panel.querySelectorAll('[data-boss-slot]'))b.setAttribute('aria-pressed',String(b.dataset.bossSlot===slot));for(const b of panel.querySelectorAll('[data-boss-weapon]'))b.setAttribute('aria-pressed',String(b.dataset.bossWeapon===weapon));if(slot!=='all'){
 let visible=0;
 for(const card of $('boss-results').querySelectorAll('.boss-card')){
  let found=false;
  for(const row of card.querySelectorAll('[data-drop-item]')){
   const item=items.get(row.dataset.dropItem),jewelry=['accessory','ring2','neck','ear','ear2'].includes(item?.slot);
   const matches=!!item&&item.kind==='equipment'&&(slot==='jewelry'?jewelry:item.slot===slot||slot==='offhand'&&item.shield)&&(slot!=='weapon'||weapon==='all'||item.weaponType===weapon);
   row.hidden=!matches;if(matches)found=true;
  }
  card.hidden=!found;if(found){visible++;for(const details of card.querySelectorAll('.observed-drops,.legacy-drops'))details.open=true;}
 }
 $('boss-count').textContent=visible+' 層頭目';
 if(!visible)$('boss-results').innerHTML=noResults('目前沒有符合篩選的已確認掉落裝備。');
}}
 for(const b of panel.querySelectorAll('[data-boss-slot]'))b.onclick=()=>{slot=b.dataset.bossSlot;weapon='all';render();};for(const b of panel.querySelectorAll('[data-boss-weapon]'))b.onclick=()=>{weapon=b.dataset.bossWeapon;render();};$('boss-search').oninput=render;$('boss-floor').oninput=render;$('boss-reset').onclick=()=>{slot='all';weapon='all';$('boss-search').value='';$('boss-floor').value='all';render();};render();
}
function downloadText(name,body,type='text/plain'){const url=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportMaterialsCSV(){const quote=x=>'"'+String(x??'').replaceAll('"','""')+'"',rows=[['素材','章節','樓層','步驟','需求數量','指定怪物','掉落率']];for(const ch of D.chapters)for(const [i,s]of(ch.steps||[]).entries())if(s.goal?.kind==='collect')rows.push([itemName(s.goal.itemId),titleChapter(ch),ch.floor,i+1,s.goal.qty||1,s.goal.from?mobName(s.goal.from):'劇情條件',legacyDropChance(s.goal.from,s.goal.itemId)===null?'待確認':legacyRate(legacyDropChance(s.goal.from,s.goal.itemId))+'（舊版參考）']);downloadText('任務素材掉落機率.csv','\ufeff'+rows.map(r=>r.map(quote).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
function classicMaterials(params){materials(params);const button=document.createElement('button');button.className='button secondary';button.textContent='下載完整 CSV ↓';main.querySelector('.page-intro').append(button);button.onclick=()=>{const quote=x=>'"'+String(x??'').replaceAll('"','""')+'"';const rows=[['素材','章節','樓層','步驟','需求數量','指定怪物','掉落率']];for(const ch of D.chapters)for(const [i,s]of(ch.steps||[]).entries())if(s.goal?.kind==='collect')rows.push([itemName(s.goal.itemId),titleChapter(ch),ch.floor,i+1,s.goal.qty||1,s.goal.from?mobName(s.goal.from):'劇情條件',legacyDropChance(s.goal.from,s.goal.itemId)===null?'待確認':legacyRate(legacyDropChance(s.goal.from,s.goal.itemId))+'（舊版參考）']);downloadText('任務素材掉落機率.csv','\ufeff'+rows.map(r=>r.map(quote).join(',')).join('\r\n'),'text/csv;charset=utf-8');};}
function classicAbout(){about();main.insertAdjacentHTML('beforeend','<section class="panel" style="margin-top:18px"><h2>資料下載</h2><div class="download-list"><button class="button secondary" id="classic-download-csv">任務素材掉率 CSV ↓</button><button class="button secondary" id="classic-download-json">完整攻略資料 JSON ↓</button></div></section>');$('classic-download-csv').onclick=exportMaterialsCSV;$('classic-download-json').onclick=()=>downloadText('guide-data.json',JSON.stringify(D,null,2),'application/json');}
function achievements(params){
 const titles=D.achievementTitles,titleMap=new Map(titles.map(x=>[x.titleId,x]));
 const categories={collect:'收集／上繳',hunt:'討伐',boss:'首領',meta:'成就累計',fun:'趣味',unknown:'待確認'};
 const catalog=window.SAO_ACHIEVEMENTS;const baseRows=catalog.entries.map(x=>({...x,fromTitle:false,title:x.title||null,stat:x.stat||null,value:Number.isFinite(x.value)?x.value:null,prog:x.target===null?null:[null,x.target]}));
 const rows=baseRows;let sortKey='order',sortDir='asc';
 main.innerHTML=intro('DATABASE / ACHIEVEMENTS','成就圖鑑','查詢已知達成條件、獎勵稱號與永久能力加成。')+`<div class="notice" id="achievement-coverage"><strong>收錄 ${nf(catalog.total)} 項成就：收集 ${nf(catalog.counts.collect??0)}、討伐 ${nf(catalog.counts.hunt??0)}、首領 ${nf(catalog.counts.boss??0)}、趣味 ${nf(catalog.counts.fun??0)}。</strong>其中 ${nf(catalog.hidden)} 項在遊戲內未公開，保留隱藏；加成保留完整回傳精度。</div><div class="filters"><input id="achievement-search" type="search" aria-label="搜尋成就或稱號" placeholder="搜尋成就、稱號、條件或裝備…"><select id="achievement-category" aria-label="成就條件類型"><option value="all">全部條件類型</option>${Object.entries(categories).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select><button class="button secondary small" id="achievement-reset">重設篩選</button><span class="count" id="achievement-count" role="status" aria-live="polite"></span></div><p class="section-note" id="achievement-help">點欄名切換排序。「待確認」代表尚未取得資料，並非加成為 0；分類、條件與獎勵依遊戲成就清單列出；不包含角色已完成狀態或當前進度。</p><div class="table-wrap gear-table-wrap" role="region" aria-label="成就條件與獎勵比較表，可左右捲動" aria-describedby="achievement-help" tabindex="0"><table class="gear-table"><thead id="achievement-head"></thead><tbody id="achievement-results"></tbody></table></div>`;
 if(params.get('id')){const selected=baseRows.find(x=>x.id===params.get('id')||x.aliases?.includes(params.get('id'))),title=titleMap.get(params.get('id'));$('achievement-search').value=selected&&!selected.hidden?selected.name:title&&known(text(title.name))?text(title.name):params.get('id');}
 function titleName(id){const t=titleMap.get(id);return t&&known(text(t.name))?text(t.name):'名稱未公開';}
 function reward(x){if(x.hidden)return'未公開';if(x.displayBonus)return esc(x.displayBonus);return x.stat&&x.value!==null?`${esc(statName(x.stat))} ${x.value>0?'+':''}${(x.value*100).toLocaleString('zh-TW',{maximumFractionDigits:8})}%`:'—';}
 function requirement(x){if(x.fromTitle)return pending;if(x.hidden)return'未公開';if(x.prog)return'目標 '+nf(x.prog[1]);if(x.parts.length)return'需完成 '+x.parts.length+' 個上繳部件';return'依條件描述';}
 function condition(x){if(x.hidden)return'未公開';let html=known(x.desc)?esc(x.desc):pending;if(x.parts.length)html+=`<details><summary>${x.parts.some(p=>p.bases.length)?'上繳部件與可用裝備':'上繳部件'}（${x.parts.length}）</summary><ul>${x.parts.map(p=>`<li>${esc(p.label||'部件名稱待確認')}${p.bases.length?'<div>'+p.bases.map(id=>`<a href="${href('equipment',id)}">${esc(itemName(id))}</a>`).join('、')+'</div>':''}</li>`).join('')}</ul></details>`;return html;}
 function value(x,key){return key==='name'?known(x.name)?x.name:x.id:key==='cat'?categories[x.cat]:key==='requirement'?x.prog?.[1]??x.parts.length:key==='reward'?x.displayValue??(x.stat&&x.value!==null?x.value:null):rows.indexOf(x);}
 function render(){const q=$('achievement-search').value.trim().toLowerCase(),cat=$('achievement-category').value;const result=rows.filter(x=>(cat==='all'||x.cat===cat)&&(!q||[x.id,x.hidden?'':x.name,x.hidden?'':x.desc,x.hidden?'':x.titleName||(x.title?titleName(x.title):''),...x.parts.flatMap(p=>[p.label,...p.bases.map(itemName)])].join(' ').toLowerCase().includes(q))).sort((a,b)=>{const av=value(a,sortKey),bv=value(b,sortKey);if(av===null||bv===null)return av===bv?0:av===null?1:-1;const cmp=typeof av==='string'?av.localeCompare(String(bv),'zh-Hant',{numeric:true}):av-bv;return sortDir==='asc'?cmp:-cmp;});
  const columns=[['name','成就名稱'],['cat','分類'],['desc','達成條件'],['requirement','階段／需求'],['reward','永久能力加成'],['title','獎勵稱號']];
  $('achievement-head').innerHTML='<tr>'+columns.map(([key,label])=>`<th scope="col"${['name','cat','requirement','reward'].includes(key)?` aria-sort="${sortKey===key?(sortDir==='asc'?'ascending':'descending'):'none'}"`:''}>${['name','cat','requirement','reward'].includes(key)?`<button class="gear-sort-button" data-ach-sort="${key}">${label}<span aria-hidden="true">${sortKey===key?(sortDir==='asc'?'↑':'↓'):'↕'}</span></button>`:label}</th>`).join('')+'</tr>';
  $('achievement-results').innerHTML=result.length?result.map(x=>`<tr data-achievement="${esc(x.id)}"><td class="gear-name"><strong>${x.hidden?'未公開成就':known(x.name)?esc(x.name):'稱號名稱待確認'}</strong>${!known(x.name)?'<small class="subtle">'+esc(x.id)+'</small>':''}</td><td>${esc(categories[x.cat])}</td><td class="gear-source">${condition(x)}</td><td>${requirement(x)}</td><td>${reward(x)}</td>${'<td>'+(x.hidden?'未公開':x.titleName?esc(x.titleName):x.title?esc(titleName(x.title)):'—')+'</td>'}</tr>`).join(''):`<tr><td colspan="${columns.length}">沒有符合的成就或稱號，請調整搜尋與篩選。</td></tr>`;
  $('achievement-count').textContent=`${result.length} / ${rows.length} 項成就`;for(const button of $('achievement-head').querySelectorAll('[data-ach-sort]'))button.onclick=()=>{const key=button.dataset.achSort;if(sortKey===key)sortDir=sortDir==='asc'?'desc':'asc';else{sortKey=key;sortDir=key==='reward'?'desc':'asc';}render();};
 }
 $('achievement-search').oninput=render;$('achievement-category').onchange=render;$('achievement-reset').onclick=()=>{$('achievement-search').value='';$('achievement-category').value='all';sortKey='order';sortDir='asc';render();};
 render();
}
function materialHub(params){if(params.get('view')==='quests'||params.has('id')){classicMaterials(params);document.title='任務素材（獨特）｜SAO 攻略資料庫';$('breadcrumb').textContent='任務素材（獨特）';main.querySelector('.page-intro')?.insertAdjacentHTML('afterend',materialCatalogue.tabs(true));}else materialCatalogue.render(params);}
return{home,equipment,monsters:monstersPage,bosses:classicBosses,materials:materialHub,skills,unique,floors,speed,about:classicAbout,achievements};
}};
